            size = 4
        }

        // take one from the `size` titles with the most copies
        for i := 0; i < size; i++ {
            counts[i]--
        }
        total += price[size]
        sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
    }
    return total
}
