```go
package bookstore

import "sort"

// Cost returns the minimum total price (in cents) for the given basket of books.
// Each book is identified by an integer 1-5 (the five books in the series).
func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		counts[b-1]++
	}
	sort.Sort(sort.Reverse(sort.IntSlice(counts[:])))

	// price[k] is the cost of a group of k distinct books.
	price := [6]int{0, 800, 1520, 2160, 2560, 3000}

	memo := make(map[[5]int]int)

	var solve func(c [5]int) int
	solve = func(c [5]int) int {
		if c[0] == 0 {
			return 0
		}
		if v, ok := memo[c]; ok {
			return v
		}
		// number of distinct titles with at least one copy
		distinct := 0
		for _, x := range c {
			if x > 0 {
				distinct++
			}
		}
		best := 1 << 30
		// try every group size from 1 to distinct
		for size := 1; size <= distinct; size++ {
			// try every choice of `size` titles to take one copy from
			for mask := 0; mask < 32; mask++ {
				if bitsOnes(mask) != size {
					continue
				}
				nc := c
				valid := true
				for i := 0; i < 5; i++ {
					if mask&(1<<i) != 0 {
						if c[i] == 0 {
							valid = false
							break
						}
						nc[i]--
					}
				}
				if !valid {
					continue
				}
				sort.Sort(sort.Reverse(sort.IntSlice(nc[:])))
				if cost := price[size] + solve(nc); cost < best {
					best = cost
				}
			}
		}
		memo[c] = best
		return best
	}

	return solve(counts)
}

func bitsOnes(mask int) int {
	n := 0
	for mask > 0 {
		n += mask & 1
		mask >>= 1
	}
	return n
}
```

