package bookstore

import "sort"

// Cost returns the total price, in cents, of the given basket of books,
// applying the largest possible discount. Each element of books is the
// title (1-5) of a book in the series.
func Cost(books []int) int {
	// c[i] is the number of copies of title i+1. c[5] is a sentinel (0).
	c := [6]int{}
	for _, b := range books {
		c[b-1]++
	}
	sort.Sort(sort.Reverse(sort.IntSlice(c[:5])))

	// price[k] is the cost of a group of k distinct books.
	price := [6]int{0, 800, 1520, 2160, 2560, 3000}

	// n[k] is the number of groups of size k in the histogram grouping:
	// each "row" of the histogram of counts forms one group.
	n := [6]int{}
	for k := 1; k <= 5; k++ {
		n[k] = c[k-1] - c[k]
	}

	// A group of 5 plus a group of 3 costs 3000+2160=5160, while two groups
	// of 4 cost 2560+2560=5120. Converting a (5,3) pair into two 4-groups is
	// always valid (it preserves the per-title usage) and always cheaper, so
	// do as many of these conversions as possible.
	k := n[5]
	if n[3] < k {
		k = n[3]
	}
	n[5] -= k
	n[3] -= k
	n[4] += 2 * k

	total := 0
	for size := 1; size <= 5; size++ {
		total += n[size] * price[size]
	}
	return total
}
